/* Browser-only JavaScript exercises. Student code runs in a sandboxed worker. */
let activeLabRun=null;
function labEscape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function labDraftKey(){return 'web-talim:lab:v1:'+currentModule+':'+currentLesson;}
function renderCodingLab(lab){
 const panel=document.createElement('section');panel.id='panel5';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab5');panel.hidden=true;
 panel.innerHTML=`<h2>Amaliy kod yozish</h2><p class="lab-language">JavaScript • Amaliy vazifa</p><h3>${labEscape(lab.title)}</h3><p>${labEscape(lab.description)}</p><details class="lab-cases"><summary>Sinov misollari va kutiladigan natijalar</summary><div class="table-scroll"><table><thead><tr><th>Kirish argumentlari</th><th>Kutiladigan return</th></tr></thead><tbody>${lab.tests.map(t=>`<tr><td><code>${labEscape(JSON.stringify(t.args))}</code></td><td><code>${labEscape(JSON.stringify(t.expected))}</code></td></tr>`).join('')}</tbody></table></div></details><label for="lab-editor" class="lab-label">Kodingiz</label><p class="muted">Funksiya nomi va parametrlarini saqlang. Natijani <code>return</code> bilan qaytaring; konsol uchun <code>console.log(...)</code> ishlating.</p><textarea id="lab-editor" class="lab-editor" spellcheck="false" autocapitalize="off" autocomplete="off" aria-describedby="lab-draft"></textarea><p id="lab-draft" class="muted">Kod shu brauzerda saqlanadi; boshqa qurilmaga avtomatik ko‘chmaydi.</p><details class="lab-input"><summary>prompt() uchun kirish qiymatlari</summary><label for="lab-input">Har bir javobni yangi qatorda yozing</label><textarea id="lab-input" rows="3" placeholder="8&#10;12"></textarea><p class="muted">prompt() navbatdagi qatorni satr sifatida oladi. Qator tugasa null qaytaradi.</p></details><div class="lab-actions"><button type="button" class="cta" id="lab-run" onclick="runCodingLab(false)">▶ Kodni bajarish</button><button type="button" class="cta" id="lab-check" onclick="runCodingLab(true)">Yechimni tekshirish</button><button type="button" class="retry" id="lab-stop" onclick="stopCodingLab(true)" disabled>To‘xtatish</button><button type="button" class="retry" onclick="resetCodingLab()">Boshlang‘ich kod</button><button type="button" class="retry" onclick="downloadCodingLab()">Kodni yuklab olish ↓</button></div><p id="lab-status" role="status">Kodni yozing va ishga tushiring.</p><h3>Natija konsoli</h3><pre id="lab-output" class="lab-output" tabindex="0" aria-label="Dastur natijasi">Natija shu yerda chiqadi.</pre><div id="lab-checks" aria-live="polite"></div><p class="muted">Sinxron JavaScript mashqlari uchun. Kod serverda bajarilmaydi. Bajarish vaqti 2 soniya bilan cheklangan. Bu konsolda HTML sahifasi, Python yoki CMD buyruqlari bajarilmaydi.</p><button type="button" class="cta" onclick="openResource(3)">6. Test sinoviga o‘tish →</button>`;
 document.querySelector('.article').appendChild(panel);
 const editor=document.getElementById('lab-editor');let draft=null;
 try{draft=localStorage.getItem(labDraftKey());}catch(e){document.getElementById('lab-draft').textContent='Brauzerda saqlash mavjud emas. Kodingizni faylga yuklab olishingiz mumkin.';}
 editor.value=draft??lab.starter;
 editor.addEventListener('input',()=>{try{localStorage.setItem(labDraftKey(),editor.value);document.getElementById('lab-draft').textContent='Kod shu brauzerda saqlandi. Boshqa qurilmaga avtomatik ko‘chmaydi.';}catch(e){document.getElementById('lab-draft').textContent='Saqlash imkoni yo‘q. Kodni faylga yuklab oling.';}});
 editor.addEventListener('keydown',event=>{if(event.key==='Tab'){event.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('  ',start,end,'end');editor.dispatchEvent(new Event('input'));}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();runCodingLab(false);}});
}
function setLabBusy(busy){for(const id of ['lab-run','lab-check']){const b=document.getElementById(id);if(b)b.disabled=busy;}const stop=document.getElementById('lab-stop');if(stop)stop.disabled=!busy;}
function stopCodingLab(notify=false){if(activeLabRun){clearTimeout(activeLabRun.timer);window.removeEventListener('message',activeLabRun.listener);activeLabRun.frame.remove();activeLabRun=null;}setLabBusy(false);if(notify&&document.getElementById('lab-status'))document.getElementById('lab-status').textContent='Bajarish to‘xtatildi. Kodni tuzatib qayta urinishingiz mumkin.';}
function resetCodingLab(){stopCodingLab();const editor=document.getElementById('lab-editor');editor.value=activeData().lab.starter;editor.dispatchEvent(new Event('input'));document.getElementById('lab-output').textContent='Natija shu yerda chiqadi.';document.getElementById('lab-checks').replaceChildren();document.getElementById('lab-status').textContent='Boshlang‘ich kod tiklandi.';editor.focus();}
function downloadCodingLab(){const text=document.getElementById('lab-editor').value;const url=URL.createObjectURL(new Blob([text],{type:'text/javascript;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`m${currentModule}-${currentLesson}-yechim.js`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function codingLabWorker(){
 const send=self.postMessage.bind(self);let lines=[],chars=0;
 const format=v=>{if(typeof v==='string')return v;if(v===undefined)return 'undefined';try{return JSON.stringify(v);}catch(e){return String(v);}};
 const output=(...args)=>{if(lines.length>=100||chars>=12000)return;const line=args.map(format).join(' ').slice(0,2000);lines.push(line);chars+=line.length;};
 const same=(a,b)=>{if(typeof a==='number'&&typeof b==='number')return Number.isFinite(a)&&Math.abs(a-b)<=1e-9*Math.max(1,Math.abs(b));if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b))return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&same(a[k],b[k]));};
 self.onmessage=event=>{const task=event.data;let index=0;try{const supplied=task.inputs;const prompt=()=>index<supplied.length?supplied[index++]:null;const console={log:output,info:output,warn:(...x)=>output('Ogohlantirish:',...x),error:(...x)=>output('Xato:',...x),clear:()=>{lines=[];chars=0;}};
 const fn=new Function('console','prompt','alert','"use strict";\n'+task.code+'\n;return typeof '+task.functionName+' === "function" ? '+task.functionName+' : null;')(console,prompt,output);
 const checks=[];if(task.check){if(typeof fn!=='function')throw new Error(task.functionName+' funksiyasi topilmadi. Funksiya nomini tekshiring.');for(const t of task.tests){try{const actual=fn(...structuredClone(t.args));checks.push({ok:same(actual,t.expected),actual:format(actual),expected:format(t.expected),args:format(t.args)});}catch(error){checks.push({ok:false,actual:String(error.name+': '+error.message),expected:format(t.expected),args:format(t.args)});}}}
 send({kind:'done',lines,checks,check:task.check});}catch(error){send({kind:'error',lines,error:String(error.name+': '+error.message).slice(0,1800)});}};
}
function runCodingLab(check){
 stopCodingLab();const lab=activeData().lab||activeData().assignment?.runner;if(!lab)return;const editor=document.getElementById('lab-editor'),code=editor.value;if(code.length>50000){document.getElementById('lab-status').textContent='Kod 50 000 belgidan oshmasin.';return;}
 const output=document.getElementById('lab-output'),status=document.getElementById('lab-status');output.textContent='Bajarilmoqda…';document.getElementById('lab-checks').replaceChildren();status.textContent=check?'Yechim sinovlardan o‘tkazilmoqda…':'Kod bajarilmoqda…';setLabBusy(true);
 const frame=document.createElement('iframe');frame.hidden=true;frame.title='Ajratilgan JavaScript bajarish muhiti';frame.setAttribute('sandbox','allow-scripts');frame.referrerPolicy='no-referrer';
 const task={code,check,functionName:lab.functionName,tests:lab.tests,inputs:document.getElementById('lab-input').value.split('\n')};
 const source='('+codingLabWorker.toString()+')();';
 const bootstrap=`const parentWindow=parent;const source=${JSON.stringify(source)};let used=false;addEventListener('message',e=>{if(e.source!==parentWindow||used)return;used=true;try{const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));const worker=new Worker(url);URL.revokeObjectURL(url);const timer=setTimeout(()=>{worker.terminate();parentWindow.postMessage({kind:'timeout'},'*');},2000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();parentWindow.postMessage(e.data,'*');};worker.onerror=e=>{clearTimeout(timer);worker.terminate();parentWindow.postMessage({kind:'error',error:e.message,lines:[]},'*');};worker.postMessage(e.data);}catch(error){parentWindow.postMessage({kind:'error',error:error.message,lines:[]},'*');}});parentWindow.postMessage({kind:'ready'},'*');`;
 frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' blob:; worker-src blob:; connect-src 'none';"><script>${bootstrap.replace(/<\/script/gi,'<\\/script')}<\/script>`;
 const listener=event=>{if(!activeLabRun||event.source!==frame.contentWindow)return;const result=event.data;if(!result||typeof result.kind!=='string')return;if(result.kind==='ready'){frame.contentWindow.postMessage(task,'*');return;}
 if(!['done','error','timeout'].includes(result.kind))return;
 output.textContent=Array.isArray(result.lines)&&result.lines.length?result.lines.slice(0,100).map(x=>String(x).slice(0,2000)).join('\n').slice(0,12000):'console.log orqali natija chiqarilmadi.';
 if(result.kind==='timeout'){status.textContent='2 soniyalik vaqt tugadi. Siklning tugash shartini tekshiring.';output.textContent+='\nBajarish avtomatik to‘xtatildi.';}
 else if(result.kind==='error'){status.textContent='Kodda xato bor. Tuzatib qayta bajaring.';output.textContent+='\n'+String(result.error).slice(0,1800);}
 else if(check&&Array.isArray(result.checks)){const checks=result.checks.slice(0,20),passed=checks.filter(t=>t.ok).length;status.textContent=`Amaliy sinov: ${passed} / ${lab.tests.length} ta o‘tdi.`;const box=document.getElementById('lab-checks');box.innerHTML=`<h3>${passed===lab.tests.length?'✓ Barcha namunaviy sinovlardan o‘tdingiz':'Yechimni tuzatish kerak'}</h3>`;for(const t of checks){const row=document.createElement('p');row.className=t.ok?'correct':'incorrect';row.textContent=`${t.ok?'✓':'✗'} Kirish: ${String(t.args).slice(0,1500)} → kutilgan: ${String(t.expected).slice(0,1500)}; sizda: ${String(t.actual).slice(0,1500)}`;box.appendChild(row);}const note=document.createElement('p');note.className='muted';note.textContent='Bu mashq uchun namunaviy tekshiruv. Nazariy test bahosi alohida hisoblanadi.';box.appendChild(note);}
 else status.textContent='Kod bajarildi. Natijani tekshiring.';stopCodingLab();};
 activeLabRun={frame,listener,timer:setTimeout(()=>{if(activeLabRun?.frame===frame){status.textContent='Bajarish muhiti javob bermadi. Qayta urinib ko‘ring.';stopCodingLab();}},5000)};window.addEventListener('message',listener);document.body.appendChild(frame);
}
